using System;
using System.Collections.Generic;

class Program
{
    static int CountVowels(string text)
    {
        string vowels = "аеёиоуыэюяaeiou";
        int count = 0;
        foreach (char letter in text.ToLower())
        {
            if (vowels.Contains(letter))
            {
                count = count + 1;
            }
        }
        return count;
    }
}

